{"success": true, "data": {"stdout": "def build_trajectory_index(traj_path, normalize_roles=False):
    index = {}
    with open(traj_path) as f:
        for row_idx, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            raw = json.loads(line)
            steps = []
            for s in raw.get("trajectory") or []:
                role = s.get("role", "unknown")
                if normalize_roles and role == "assistant":
                    role = "ai"
                steps.append({
                    "role": role,
                    "text": s.get("text") or s.get("system_prompt") or "",
                })
            index[row_idx] = steps
    return index

